const char *i18n(LangId lang, StrId id)
{
    if (lang < 0 || lang >= LANG_COUNT) lang = LANG_EN;
    const char *s = g_languages[lang].strings[id];
    if (!s) s = g_languages[LANG_EN].strings[id];
    return s ? s : "";
}

const Language *i18n_language(LangId lang)
{
    if (lang < 0 || lang >= LANG_COUNT) lang = LANG_EN;
    return &g_languages[lang];
}

LangId i18n_from_code(const char *code)
{
    if (!code) return LANG_EN;
    for (int i = 0; i < LANG_COUNT; i++)
        if (strcasecmp(code, g_languages[i].code) == 0) return (LangId)i;
    return LANG_EN;
}
